<script lang="ts">
 import {adminClinicsApi} from '#lib/api/admin/clinics.ts';import {apiMessage} from '#lib/admin/scheduling.ts';import {canAccessFeature} from '#lib/feature-access.ts';import {Button} from '#lib/components/ui/button/index.ts';import Feedback from './Feedback.svelte';import type {MedicalFacility,FacilityAnalytics,VisitorCount,DoctorDurations} from '#lib/types/clinic.ts';
 let {facility,stats=false}:{facility:MedicalFacility;stats?:boolean}=$props();let range=$state(30),revision=$state(0),loading=$state(true),error=$state(''),data=$state<FacilityAnalytics|null>(null),visitor=$state<VisitorCount|null>(null),doctors=$state<DoctorDurations|null>(null);const accessible=$derived(canAccessFeature(facility,stats?'advanced_queue':'analytics'));
 $effect(()=>{const id=facility.id,days=range,allowed=accessible,s=stats,r=revision;void r;let live=true;loading=true;error='';data=null;visitor=null;doctors=null;(async()=>{try{if(s){if(allowed){const v=await adminClinicsApi.doctorDurations(id,{range:days});if(live)doctors=v;}}else{const results=await Promise.allSettled([adminClinicsApi.visitorCount(id,{range:days}),allowed?adminClinicsApi.analytics(id,{range:days,granularity:days===90?'week':'day'}):Promise.resolve(null)]);if(live){if(results[0].status==='fulfilled')visitor=results[0].value;else error=apiMessage(results[0].reason,'訪客資料載入失敗');if(results[1].status==='fulfilled')data=results[1].value;else error=apiMessage(results[1].reason,'完整分析載入失敗');}}}catch(e){if(live)error=apiMessage(e,'統計載入失敗');}finally{if(live)loading=false;}})();return()=>{live=false;};});
 const method:Record<string,string>={phone:'電話',walk_in:'現場',online:'線上'};
</script>
<div class="space-y-5"><div class="flex flex-wrap gap-2" aria-label="分析日期範圍">{#each [7,30,90] as days (days)}<Button variant={range===days?'default':'outline'} onclick={()=>range=days}>近 {days} 天</Button>{/each}</div><Feedback {error}/>{#if error}<Button variant="outline" onclick={()=>revision++}>重試分析資料</Button>{/if}{#if loading}<p role="status">載入分析中…</p>{:else}{#if visitor}<div class="grid gap-3 sm:grid-cols-2"><div class="rounded-2xl border bg-card p-5"><h2 class="text-sm text-muted-foreground">公開頁不重複造訪人數</h2><p class="mt-2 text-3xl font-semibold">{visitor.page_view_count??0}</p></div><div class="rounded-2xl border bg-card p-5"><h2 class="text-sm text-muted-foreground">有預約的不重複客戶</h2><p class="mt-2 text-3xl font-semibold">{visitor.visitor_count}</p></div></div>{/if}{#if !accessible}<section class="space-y-3 rounded-2xl border bg-card p-6"><h2 class="font-semibold">{stats?'看診統計':'完整客戶分析'}為專業方案功能</h2><p class="text-sm text-muted-foreground">院所目前尚未開通此功能，可查看方案或啟用符合資格的試用。</p><Button variant="outline" href="/admin/subscription">查看訂閱</Button></section>{:else if stats&&doctors}<p class="text-sm text-muted-foreground">看診時長：看診中至完成；等待時間：報到至叫號。</p><div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{#each doctors.doctors as d (d.staff_id??'none')}<article class="space-y-3 rounded-2xl border bg-card p-5"><h2 class="font-semibold">{d.staff_name??'不指定人員'}</h2><p>平均看診 {d.avg_consult_minutes??'—'} 分鐘</p><p>平均等待 {d.avg_wait_minutes??'—'} 分鐘</p><p class="text-xs text-muted-foreground">看診 {d.consult_count} 筆 · 等待 {d.wait_count} 筆{d.consult_count<3?'・樣本不足，僅供參考':''}</p></article>{:else}<p class="rounded-xl border p-8 text-muted-foreground">尚無看診統計；完成報到、叫號與服務後即可累積。</p>{/each}</div>{:else if data}<p class="text-sm text-muted-foreground">{data.start_date} 至 {data.end_date}</p><div class="grid grid-cols-2 gap-3 lg:grid-cols-4">{#each [{label:'總預約',value:data.total},{label:'已預約',value:data.confirmed},{label:'已完成',value:data.completed},{label:'已取消',value:data.cancelled},{label:'未到',value:data.no_show},{label:'未到率',value:(data.no_show_rate*100).toFixed(1)+'%'},{label:'客戶數',value:data.unique_patients},{label:'回訪率',value:(data.repeat_patient_rate*100).toFixed(1)+'%'}] as v (v.label)}<div class="rounded-xl border bg-card p-4"><h2 class="text-sm text-muted-foreground">{v.label}</h2><p class="mt-2 text-2xl font-semibold">{v.value}</p></div>{/each}</div><div class="grid gap-4 lg:grid-cols-2"><section class="space-y-3 rounded-2xl border bg-card p-5"><h2 class="font-semibold">預約趨勢</h2>{#each data.trend as p (p.period)}<div class="grid grid-cols-[6rem_1fr_2rem] items-center gap-2 text-xs"><span>{p.period}</span><div class="h-3 overflow-hidden rounded bg-muted"><div class="h-full rounded bg-primary" style:width={(p.count/Math.max(1,...data.trend.map(x=>x.count))*100)+'%'}></div></div><span>{p.count}</span></div>{:else}<p class="text-sm text-muted-foreground">尚無預約資料。</p>{/each}</section><section class="space-y-4 rounded-2xl border bg-card p-5"><h2 class="font-semibold">預約來源</h2>{#each data.by_method as p (p.method)}<div class="flex justify-between text-sm"><span>{method[p.method]??p.method}</span><span>{p.count}</span></div>{:else}<p class="text-sm text-muted-foreground">尚無來源資料。</p>{/each}</section></div><section class="space-y-3 rounded-2xl border bg-card p-5"><h2 class="font-semibold">熱門預約時段</h2><div class="grid grid-cols-3 gap-3 sm:grid-cols-6">{#each data.by_hour as h (h.hour)}<div class="rounded-lg bg-muted/50 p-3 text-center text-sm">{h.hour}:00 <span class="block font-semibold">{h.count} 筆</span></div>{:else}<p class="col-span-full text-sm text-muted-foreground">尚無時段資料。</p>{/each}</div></section>{/if}{/if}</div>
